for(const r of d.admin.assets.filter(r=>r.status==='repair'&&C.adminCan(d,u,'assets')))add('process','asset',r,today);
for(const r of d.oa.collabs.filter(r=>r.status!=='done'&&hasProject(r.project))){if(r.owner===u.person&&['pending','accepted'].includes(r.status))add('execute','collabs',r,r.due);if(r.author===u.person)add(r.status==='review'?'accept':'initiated','collabs',r,r.due)}
