function principal(d,u,r,date){if(r.status!=='pending'||u.person===r.author||!eligible(d,u.person))return '';const id=r.approvers[r.step];if(!eligible(d,id))return '';if(id===u.person)return id;return d.operations.delegates.some(x=>x.enabled&&x.principal===id&&x.delegate===u.person&&x.start<=date&&x.end>=date)&&active(d,u.person)?id:''}
