function impact(d,cmd){let ts=[];if(cmd.type==='assign'||cmd.type==='edit'&&cmd.kind==='tasks')ts=d.tasks.filter(t=>t.id===cmd.id);if(cmd.type==='operations'&&cmd.op==='batch-assign')ts=d.tasks.filter(t=>cmd.values.tasks.includes(t.id));const changed=ts.filter(t=>cmd.type==='assign'?t.owner!==cmd.owner:['owner','start','end','deps'].some(k=>cmd.values?.[k]!==undefined&&JSON.stringify(t[k])!==JSON.stringify(cmd.values[k]))||cmd.op==='batch-assign'&&t.owner!==cmd.values.owner);const touched=new Set(changed.map(t=>t.id));let n;do{n=touched.size;for(const t of d.tasks)if(t.deps.some(id=>touched.has(id))||t.parent&&touched.has(t.parent)||[...touched].some(id=>d.tasks.find(x=>x.id===id)?.parent===t.id))touched.add(t.id)}while(touched.size!==n);return {changed:changed.map(t=>({id:t.id,name:t.name,project:C.projectOf(d,t).id,before:{owner:t.owner,start:t.start,end:t.end,deps:t.deps},after:{owner:cmd.owner||cmd.values?.owner||t.owner,start:cmd.values?.start||t.start,end:cmd.values?.end||t.end,deps:cmd.values?.deps||t.deps}})),affected:d.tasks.filter(t=>touched.has(t.id)&&!changed.includes(t)),milestones:d.milestones.filter(m=>d.tasks.some(t=>touched.has(t.id)&&t.milestone===m.id))}}
function scoped(d,u,opts){const scopedDate=opts?.asOf||today(),v=atDate(scopedDate,()=>old.scoped(d,u,opts)),o=v.operations;scopedDates.set(v,scopedDate);for(const t of v.tasks)if(!running(d,C.projectOf(d,t)?.id))pausedTasks.add(t);const date=opts?.asOf||new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});v.oa.requests=v.oa.requests.filter(r=>old.oaVisible(d,u,'requests',r)||principal(d,u,r,date));const has=id=>v.projects.some(p=>p.id===id);o.risks=o.risks.filter(r=>canRisk(d,u,r)&&(opts?.archived||project(d,r.project)?.lifecycle!=='archived'));o.observations=o.observations.filter(r=>v.governance.outcomes.some(x=>x.id===r.metric));o.commitments=o.commitments.filter(r=>C.memberVisible(d,u,r.member)&&v.tasks.some(t=>t.id===r.task));o.covers=o.covers.filter(r=>r.subject===u.person||r.substitute===u.person||C.adminCan(d,u,'personnel')||person(d,r.subject)?.reportsTo===u.person);o.templates=o.templates.filter(r=>r.owner===u.person);v.history=v.history.filter(h=>h.access?.kind!=='private-template'||h.access.member===u.person);for(const h of d.history.filter(h=>h.access?.kind==='private-template'&&h.access.member===u.person))if(!v.history.some(x=>x.id===h.id))v.history.push(C.clone(h));return v}
function inbox(d,u,date){const rows=atDate(date,()=>old.inbox(d,u,date)).filter(r=>!r.project||running(d,r.project));for(const row of rows){const r=row.kind==='requests'&&d.oa.requests.find(r=>r.id===row.id);if(r?.status==='pending'&&r.approvalDue){row.date=r.approvalDue;row.late=row.date<date}}for(const r of d.oa.requests){if(principal(d,u,r,date)&&!rows.some(x=>x.kind==='requests'&&x.id===r.id&&x.category==='approve')&&running(d,r.project))rows.push({key:'approve:requests:'+r.id,category:'approve',kind:'requests',id:r.id,title:'代审 · '+r.title,date:r.approvalDue||r.due,project:r.project,priority:'P1',late:(r.approvalDue||r.due)<date})}for(const r of d.operations.risks.filter(r=>r.owner===u.person&&r.status==='open'&&running(d,r.project)))rows.push({key:'process:managed-risk:'+r.id,category:'process',kind:'managed-risk',id:r.id,title:'风险处理 · '+r.title,date:r.due,project:r.project,priority:r.priority||'P1',late:r.due<date});for(const r of d.operations.covers.filter(r=>r.substitute===u.person&&r.status==='proposed'))rows.push({key:'accept:coverage:'+r.id,category:'accept',kind:'coverage',id:r.id,title:'确认临时接手安排',date:r.start,project:'',priority:'P1',late:r.start<date});return rows.sort((a,b)=>Number(b.late)-Number(a.late)||a.priority.localeCompare(b.priority)||a.date.localeCompare(b.date))}
